var MAPDATA = {"W": 2048, "H": 1536, "marks": [{"name": "恓鸟城", "sub": "西部 · 山城军邦", "x": 0.17, "y": 0.55, "imp": 1, "desc": "西部大陆断脊山脉南段西侧内陆，延西河中游西侧。别称“悲息之城”，冶铁业冠绝沧陆，兵器甲胄精良耐用。宗族长老制加卫国者庭军事制衡，战士信奉“以血作衣，以峰作干”。"}, {"name": "茹章城", "sub": "中部 · 神权霸主", "x": 0.5, "y": 0.38, "imp": 1, "desc": "中部平原，眸霞山脉东侧山脚，连奕江北岸西侧，地图地理正中心。沧陆公认最繁荣强大的城邦，疆域为诸邦之最。然而“永恒繁荣”以全城邦世代的寿命为代价——所有茹章人都活不过45岁。"}, {"name": "眴姚城", "sub": "东部 · 商贸港城", "x": 0.9, "y": 0.35, "imp": 1, "desc": "盎季地东部沿海，屈海东侧、东枝崖西侧，苍瀛海沿岸港口。沧陆东部最大港口，海商公会共治，全沧陆的信息交汇地与商品集散地。"}, {"name": "伏熏城", "sub": "南部 · 海岛民主之邦", "x": 0.12, "y": 0.87, "imp": 1, "desc": "伏熏岛中部腹地，狩脊山西侧，之丝运河核心枢纽。政团民主制，十年换届选举；对外管控森严，外来商人只能在东部平安港活动。"}, {"name": "西部大陆", "sub": "主陆块 · 西北至西南", "x": 0.28, "y": 0.35, "imp": 1, "desc": "元荒海东岸、白绫海南侧、肆星海西北侧的大片陆块。全境纵贯断脊山脉，向南延伸出东生半岛，内陆核心城镇恓鸟城。"}, {"name": "中部大陆", "sub": "主陆块 · 地图正中央", "x": 0.58, "y": 0.35, "imp": 1, "desc": "眸霞山脉以东、白绫海以南、肆星海以北的中央陆块。西以眸霞山脉与西部大陆隔开，东以连奕江、吴阳湖和盎季地隔开，核心城镇茹章城。"}, {"name": "盎季地", "sub": "主陆块 · 东部巨型半岛", "x": 0.85, "y": 0.3, "imp": 1, "desc": "地图东部巨型半岛型主陆块，苍瀛海西岸、肆星海东侧。西侧渡蛟裂谷、吴阳湖与中部大陆分隔，最南端为东枝崖，沿海港口眴姚城。"}, {"name": "东生半岛", "sub": "西部大陆 · 正南延伸", "x": 0.29, "y": 0.72, "desc": "西部大陆向正南方向延伸的巨型半岛。西侧元荒海、东侧肆星海，南端隔承晚海峡正对雁南岛，西海岸为双生湾。"}, {"name": "奇迤岛", "sub": "东北上角 · 白绫海东北部", "x": 0.7, "y": 0.08, "imp": 1, "desc": "地图东北上角，白绫海东北部内海岛，斯瑜群岛西侧。西侧扼根山，中东部全域覆盖无昼碛（海岛沙漠）。"}, {"name": "雁南岛", "sub": "中西南 · 承晚海峡正南", "x": 0.29, "y": 0.91, "imp": 1, "desc": "承晚海峡正南方、肆星海西北侧的大型大陆岛。岛内中心为荻瑟湖，是西南海域的关键陆地节点。"}, {"name": "伏熏岛", "sub": "西南海域 · 火山岛", "x": 0.12, "y": 0.88, "imp": 1, "desc": "元荒海东南、肆星海西南交汇处的火山岛。岛内东部狩脊山，腹地伏熏城，之丝运河贯穿全岛。"}, {"name": "赎誓阁", "sub": "肆星海南偏 · 独立岛屿", "x": 0.6, "y": 0.75, "desc": "肆星海南偏中部独立岛屿，归尘屿北侧，盎季地正南外海。"}, {"name": "斯瑜群岛", "sub": "东北 · 两海交界", "x": 0.85, "y": 0.16, "desc": "白绫海东侧、苍瀛海西侧交界，奇迤岛东南方的小型群岛。"}, {"name": "归尘屿", "sub": "肆星海南部 · 星礁群岛", "x": 0.72, "y": 0.81, "desc": "肆星海南部、盎季地正南方的连片星礁型海岛群。"}, {"name": "星沙礁", "sub": "肆星海中部 · 暗礁群", "x": 0.46, "y": 0.77, "desc": "肆星海中部大片浅滩暗礁群，雁南岛正东、赎誓阁西北之间海域。"}, {"name": "南引群岛", "sub": "右下角 · 火山群岛", "x": 0.91, "y": 0.86, "desc": "整张地图右下角最远端，肆星海最东南端的大型火山群岛。"}, {"name": "断脊山脉", "sub": "西部大陆 · 南北走向", "x": 0.28, "y": 0.3, "imp": 1, "desc": "西部大陆全境南北走向纵向山脉，西部地形核心骨架，山脊海拔3000米以上。西北段含辞君山，南麓发源延西河，恓鸟城坐落山脉南段西侧。"}, {"name": "眸霞山脉", "sub": "中部大陆西侧 · 分界线", "x": 0.43, "y": 0.3, "imp": 1, "desc": "中部大陆西侧南北走向纵向山脉，沧陆东西核心地理分界线。主峰自鸣山，东麓平原为茹章城、连奕江流域。"}, {"name": "自鸣山", "sub": "眸霞山脉主峰 · 5243m", "x": 0.425, "y": 0.36, "imp": 1, "desc": "眸霞山脉主峰，沧陆全境最高峰（5243米），地图中部偏北高地。黄昏霞光铺满山峦，被誉为“心的温柔乡”，是沧陆公认的盛景。"}, {"name": "桓山", "sub": "白绫海南岸 · 4297m", "x": 0.5, "y": 0.13, "desc": "白绫海南岸、眸霞山脉西北侧山脚，海拔4297米，被群山环抱。民间流传“真龙降世”的传说，登顶者可向天许愿——但愿望从不会真正应验。"}, {"name": "狩脊山", "sub": "伏熏岛东部 · 2136m", "x": 0.17, "y": 0.88, "desc": "伏熏岛东部山地，海拔2136米，伏熏城东侧，是伏熏城人民瞻仰的精神圣地。山中遍植白色草木，象征一尘不染的圣洁。"}, {"name": "扼根山", "sub": "奇迤岛西部 · 1505m", "x": 0.64, "y": 0.08, "desc": "奇迤岛西部绿洲中心山峰，海拔1505米，无昼碛西边界。茹章城的隐秘信仰圣地——灵祠里沉睡着一具“不属于这个世界的神之遗骸”。"}, {"name": "辞君山", "sub": "断脊山脉西北段 · 1437m", "x": 0.21, "y": 0.2, "desc": "断脊山脉西北段山峰，海拔1437米，恓鸟城正北。山间云雾缭绕，半山处留有一处古亭悬址，是恓鸟城的文化符号。"}, {"name": "渡蛟裂谷", "sub": "盎季地西侧 · 裂谷带", "x": 0.72, "y": 0.4, "desc": "盎季地西侧、吴阳湖正东，南北走向长条峡谷，中部与东部大陆的天然分界线。"}, {"name": "东枝崖", "sub": "盎季地最南端 · 崖岸", "x": 0.86, "y": 0.52, "desc": "盎季地最南端海岸线，肆星海东北沿岸陡峭崖岸，屈海东侧边界。"}, {"name": "无昼碛", "sub": "奇迤岛中东部 · 沙漠", "x": 0.72, "y": 0.1, "desc": "奇迤岛中东部全域巨型海岛沙漠，扼根山绿洲东侧。沙粒自带吸光特性，永远笼罩灰蒙暝色，无昼夜之分，是天然的生命禁区。"}, {"name": "元荒海", "sub": "最西侧 · 外海", "x": 0.04, "y": 0.45, "imp": 1, "desc": "整张地图最西侧整片外海，全境左边界水域。东岸完整贴合西部大陆与东生半岛西侧海岸，东南侧毗邻伏熏岛，沿岸海湾为双生湾。"}, {"name": "苍瀛海", "sub": "最东侧 · 外海", "x": 0.99, "y": 0.45, "imp": 1, "desc": "整张地图最东侧整片外海，全境右边界水域。西岸贴合盎季地东部海岸线，北部与白绫海隔斯瑜群岛、望暮海峡相望，为眴姚港远洋航线主水域。"}, {"name": "白绫海", "sub": "最北部 · 陆缘内海", "x": 0.35, "y": 0.05, "imp": 1, "desc": "整张地图最北部陆缘内海，地图顶部整片封闭近海。南部贴合西部大陆、中部大陆北岸，东北侧包围奇迤岛，海域南部架设望暮大桥。"}, {"name": "肆星海", "sub": "中南部 · 核心主海域", "x": 0.5, "y": 0.68, "imp": 1, "desc": "地图中南部全域核心主海域，地图下半段大片水域。北侧接壤东生半岛、中部大陆南岸，南部散布星沙礁、赎誓阁、归尘屿、南引群岛。"}, {"name": "双生湾", "sub": "西部大陆南段 · 海湾", "x": 0.11, "y": 0.7, "desc": "西部大陆南段，元荒海东岸凹陷海湾，延西河入海口。"}, {"name": "泊月湾", "sub": "中部大陆南段 · 海湾", "x": 0.58, "y": 0.6, "desc": "中部大陆南段，肆星海北岸凹陷海湾，连奕江入海口。"}, {"name": "屈海", "sub": "盎季地东南 · 封闭内湾", "x": 0.83, "y": 0.5, "desc": "盎季地东南部内侧，被东枝崖三面环绕的半封闭海湾，属肆星海附属水域。"}, {"name": "承晚海峡", "sub": "中西南 · 水道", "x": 0.28, "y": 0.83, "desc": "东生半岛正南、雁南岛正北中间的狭长水道，连通西侧元荒海、东侧肆星海。海底铺设潜蛟海底隧道。"}, {"name": "望暮海峡", "sub": "东北上部 · 水道", "x": 0.6, "y": 0.17, "desc": "奇迤岛西南、北部大陆东北之间的水道，连通北部白绫海、东侧苍瀛海。海峡西段架设望暮大桥。"}, {"name": "吴阳湖", "sub": "中部大陆东侧 · 淡水湖", "x": 0.65, "y": 0.44, "desc": "中部大陆东侧、盎季地西侧平原，连奕江下游东岸，渡蛟裂谷正西。盛夏“灼月”为农忙收割期。"}, {"name": "荻瑟湖", "sub": "雁南岛 · 岛内湖泊", "x": 0.28, "y": 0.9, "desc": "雁南岛岛屿几何中心，岛内唯一大型内陆湖。"}, {"name": "延西河", "sub": "西部 · 自北向南", "x": 0.2, "y": 0.63, "desc": "发源于断脊山脉南麓，全程自北向南流经西部内陆、恓鸟城东侧，最终注入西部大陆南段双生湾（元荒海）。"}, {"name": "连奕江", "sub": "中部 · 自西向东", "x": 0.56, "y": 0.44, "desc": "发源于眸霞山脉东麓，自西向东横贯中部平原，途经茹章城北侧、吴阳湖南侧，最终注入中部大陆南段泊月湾（肆星海）。"}, {"name": "望暮大桥", "sub": "望暮海峡西段 · 巨型桥梁", "x": 0.57, "y": 0.19, "imp": 1, "desc": "横跨望暮海峡西段，连通中部大陆东北岸与奇迤岛西南岸，是跨区域核心交通枢纽。"}, {"name": "潜蛟海底隧道", "sub": "承晚海峡海底 · 隧道", "x": 0.29, "y": 0.81, "desc": "承晚海峡海底隧道，连通西部大陆东生半岛南端与雁南岛北侧，与望暮大桥并称沧陆两大跨海工程。"}, {"name": "之丝运河", "sub": "伏熏岛 · 南北贯通运河", "x": 0.13, "y": 0.84, "desc": "伏熏岛全境南北贯通的人工运河，以伏熏城为中心枢纽，串联全岛航运与灌溉，是海岛的经济命脉。"}], "rivers": [{"pts": [[0.3, 0.55], [0.27, 0.6], [0.23, 0.64], [0.19, 0.68], [0.15, 0.71], [0.12, 0.73]], "name": "延西河"}, {"pts": [[0.43, 0.42], [0.48, 0.4], [0.53, 0.39], [0.58, 0.4], [0.63, 0.43], [0.65, 0.47], [0.63, 0.52], [0.6, 0.56], [0.57, 0.59]], "name": "连奕江"}], "lakes": [{"x": 0.65, "y": 0.44, "r": 0.02, "name": "吴阳湖"}, {"x": 0.28, "y": 0.9, "r": 0.013, "name": "荻瑟湖"}]};

